import {analyze} from './audio.js';
import {initBatch} from './batch-ui.js';
import {normalizeLabel,labelName} from './batch.js';
import {parseCSV,groupMetrics,paired} from './metrics.js';
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={file:null,buffer:null,audio:null,inference:null,rows:[],groups:[],selected:0,synthetic:false,models:[],page:'inference',api:localStorage.getItem('deepguard-api')||'',hash:null,source:null,groundTruth:null,singleBusy:false,batchBusy:false};
let batchUI;
const colors=['#5ce1e6','#b4a2fa','#7ce6b1','#eab783','#ff8fa2','#7daeff'];
const fmt=(x,n=3)=>x==null||!Number.isFinite(x)?'—':x.toFixed(n),pct=x=>x==null?'—':(100*x).toFixed(1)+'%';
let toastTimer;
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,6500);}
function go(page){if(!['inference','batch','evaluation','features','report'].includes(page))page='inference';state.page=page;window.scrollTo(0,0);document.querySelectorAll('.page').forEach(x=>x.hidden=x.id!==`page-${page}`);document.querySelectorAll('.nav[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===page));$('crumb').textContent={inference:'Analisis audio',batch:'Analisis batch',evaluation:'Evaluasi & metrik',features:'Eksplorasi fitur',report:'Laporan analisis'}[page];history.replaceState(null,'','#'+page);if(page==='evaluation'&&state.groups.length)drawEval();if(page==='features'&&state.audio)drawFeatures();if(page==='report')renderReport();if(page==='batch')batchUI?.refresh();}
document.querySelectorAll('[data-page]').forEach(x=>x.onclick=()=>go(x.dataset.page));document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>go(x.dataset.go));
for(const wave of document.querySelectorAll('.empty-wave'))wave.innerHTML=Array.from({length:49},(_,i)=>`<i style="height:${8+Math.abs(Math.sin(i*.74)*Math.cos(i*.23))*64}px;opacity:${.25+Math.sin(i/49*Math.PI)*.6}"></i>`).join('');
for(const bars of document.querySelectorAll('.mini-bars'))bars.innerHTML=Array.from({length:18},(_,i)=>`<i style="height:${6+(Math.sin(i*1.72)+1)*12}px"></i>`).join('');
function download(name,data,type='application/json'){const blob=new Blob([typeof data==='string'?data:JSON.stringify(data,null,2)],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function surface(id){const c=$(id),w=Math.max(220,c.clientWidth),h=Number(c.dataset.logicalHeight||c.getAttribute('height')),dpr=devicePixelRatio||1;c.dataset.logicalHeight=h;c.width=w*dpr;c.height=h*dpr;c.style.height=h+'px';const ctx=c.getContext('2d');ctx.scale(dpr,dpr);ctx.fillStyle='#101a26';ctx.fillRect(0,0,w,h);return {ctx,w,h};}
function chart(id,series,{xmin=0,xmax=1,ymin=0,ymax=1,diagonal=false,xlabel='',ylabel=''}={}){const {ctx,w,h}=surface(id),l=40,r=15,t=18,b=35,W=w-l-r,H=h-t-b;ctx.font='9px monospace';for(let i=0;i<=4;i++){const x=l+W*i/4,y=t+H*i/4;ctx.strokeStyle='#263545';ctx.lineWidth=.6;ctx.beginPath();ctx.moveTo(l,y);ctx.lineTo(w-r,y);ctx.stroke();ctx.fillStyle='#7890a3';ctx.fillText(fmt(ymax-(ymax-ymin)*i/4,1),3,y+3);ctx.fillText(fmt(xmin+(xmax-xmin)*i/4,1),x-8,h-15);}if(diagonal){ctx.setLineDash([4,5]);ctx.strokeStyle='#466070';ctx.beginPath();ctx.moveTo(l,t+H);ctx.lineTo(l+W,t);ctx.stroke();ctx.setLineDash([]);}for(let si=0;si<series.length;si++){const s=series[si];ctx.strokeStyle=s.color||colors[si%colors.length];ctx.lineWidth=1.7;ctx.beginPath();let has=false;for(const p of s.points){if(p.y==null||!Number.isFinite(p.y)){has=false;continue;}const x=l+(p.x-xmin)/(xmax-xmin)*W,y=t+H-(p.y-ymin)/(ymax-ymin)*H;if(has)ctx.lineTo(x,y);else ctx.moveTo(x,y);has=true;}ctx.stroke();}ctx.fillStyle='#7890a3';ctx.fillText(xlabel,w/2,h-2);ctx.fillText(ylabel,l,11);}
function drawSignal(){const a=state.audio;if(!a)return;const {ctx,w,h}=surface('waveform');ctx.strokeStyle='#274050';ctx.beginPath();ctx.moveTo(0,h/2);ctx.lineTo(w,h/2);ctx.stroke();ctx.strokeStyle='#5ce1e6';ctx.lineWidth=1.4;a.waveform.forEach((v,i)=>{const x=i/a.waveform.length*w,amp=v/(a.peak||1)*(h*.42);ctx.beginPath();ctx.moveTo(x,h/2-amp);ctx.lineTo(x,h/2+amp);ctx.stroke();});const p=surface('spectrogram'),spec=a.spectrogram;for(let x=0;x<spec.length;x++)for(let y=0;y<128;y++){const db=spec[x][y*2],v=Math.max(0,Math.min(1,(db+90)/70));p.ctx.fillStyle=`rgb(${Math.round(15+v*72)},${Math.round(25+v*190)},${Math.round(42+v*173)})`;p.ctx.fillRect(x/spec.length*p.w,(127-y)/128*p.h,Math.ceil(p.w/spec.length),Math.ceil(p.h/128));}$('wave-end').textContent=fmt(a.duration,2)+' s';$('signal-stats').innerHTML=[['Durasi',fmt(a.duration,2)+' s'],['Level RMS',fmt(a.rms_dbfs,1)+' dBFS'],['Analisis',a.sample_rate/1000+' kHz']].map(([k,v])=>`<div class="stat"><small>${k}</small><strong>${v}</strong></div>`).join('');}
let playerURL;
async function loadFile(file){if(state.singleBusy||state.batchBusy){toast('Tunggu proses analisis selesai sebelum mengganti audio.');return;}try{state.groundTruth=singleLabel();if(file.size>25*1024*1024)throw Error('Ukuran audio maksimum 25 MB.');$('analyze').disabled=true;const data=await file.arrayBuffer(),context=new AudioContext();let buffer;try{buffer=await context.decodeAudioData(data.slice(0));}finally{await context.close();}if(buffer.duration>60||buffer.duration<.1)throw Error('Durasi audio harus 0,1–60 detik.');const n=Math.ceil(buffer.duration*16000),offline=new OfflineAudioContext(1,n,16000),source=offline.createBufferSource();source.buffer=buffer;source.connect(offline.destination);source.start();const resampled=await offline.startRendering();state.file=file;state.source=file.name;state.buffer=resampled.getChannelData(0).slice();state.hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',data)),x=>x.toString(16).padStart(2,'0')).join('');state.audio=null;state.inference=null;$('signal-empty').hidden=false;$('signal-result').hidden=true;$('features-empty').hidden=false;$('features-content').hidden=true;$('backend-feature-details').hidden=true;$('predictions').hidden=true;$('signal-label').textContent='AUDIO SIAP';$('file-details').hidden=false;$('file-name').textContent=file.name;$('file-meta').textContent=`${fmt(file.size/1024,1)} KB · ${fmt(buffer.duration,2)} s · ${buffer.sampleRate/1000} kHz decoder · ${buffer.numberOfChannels} kanal`;$('upload-title').textContent='Ganti rekaman audio';if(playerURL)URL.revokeObjectURL(playerURL);playerURL=URL.createObjectURL(file);$('player').src=playerURL;$('analyze').disabled=false;toast('Audio siap. Jalankan analisis untuk mengekstraksi fitur.');}catch(e){$('analyze').disabled=!state.buffer;toast(e.message||'Audio tidak dapat didekode browser. Coba WAV/MP3.');}}
$('audio-file').onchange=e=>{if(e.target.files[0])loadFile(e.target.files[0]);e.target.value='';};const drop=$('dropzone');for(const event of ['dragover','dragenter'])drop.addEventListener(event,e=>{e.preventDefault();drop.classList.add('drag');});for(const event of ['dragleave','drop'])drop.addEventListener(event,e=>{e.preventDefault();drop.classList.remove('drag');if(event==='drop'&&e.dataTransfer.files[0])loadFile(e.dataTransfer.files[0]);});
function sampleWav(){const n=16000*4,b=new ArrayBuffer(44+n*2),v=new DataView(b),s=(o,t)=>[...t].forEach((c,i)=>v.setUint8(o+i,c.charCodeAt(0)));s(0,'RIFF');v.setUint32(4,36+n*2,true);s(8,'WAVE');s(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,16000,true);v.setUint32(28,32000,true);v.setUint16(32,2,true);v.setUint16(34,16,true);s(36,'data');v.setUint32(40,n*2,true);for(let i=0;i<n;i++){const t=i/16000,env=Math.sin(Math.PI*i/n)**2*(.7+.3*Math.sin(2*Math.PI*2*t));const x=env*(.32*Math.sin(2*Math.PI*140*t)+.13*Math.sin(2*Math.PI*280*t)+.05*Math.sin(2*Math.PI*420*t));v.setInt16(44+i*2,x*32767,true);}return new File([b],'contoh-sintetis-140Hz.wav',{type:'audio/wav'});}
$('sample-audio').onclick=()=>loadFile(sampleWav());
async function api(path,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),options.method==='POST'?180000:8000);try{const r=await fetch(state.api+path,{...options,signal:controller.signal});if(!r.ok){let msg=`API ${r.status}`;try{const j=await r.json();msg=typeof j.detail==='string'?j.detail:msg;}catch{}throw Error(msg);}return await r.json();}finally{clearTimeout(timer);}}
async function connect(silent=false){try{const result=await api('/api/models');state.models=result.models||[];state.evaluations=result.evaluations||[];$('server-evaluations').hidden=!state.evaluations.length;$('server-evaluation-select').innerHTML=state.evaluations.map(e=>`<option value="${esc(e.id)}">${esc(e.title)}</option>`).join('');renderModels();$('connection-status').textContent=`Backend aktif · ${state.models.filter(m=>m.available!==false).length}/${state.models.length} model siap`;if(!silent)toast('Backend terhubung. '+state.models.filter(m=>m.available!==false).length+' model siap.');}catch(e){state.models=[];$('server-evaluations').hidden=true;renderModels();$('connection-status').textContent='Mode eksplorasi';if(!silent)toast('Backend tidak dapat dijangkau: '+e.message);}}
function renderModels(){
 const available=state.models.filter(m=>m.available!==false);
 $('processing-location').textContent=available.length?'Inferensi mengirim audio ke backend terpilih':'Audio diproses di perangkat Anda';
 $('model-list').innerHTML=state.models.length?['glottal_v4','residual_modulation'].map(pipeline=>{
  const models=state.models.filter(m=>(m.pipeline||'glottal_v4')===pipeline);if(!models.length)return '';
  return `<div class="model-group">${pipeline==='residual_modulation'?'RESIDUAL & MODULASI':'GLOTAL / SPEKTRAL v4/v5'}</div>`+models.map(m=>`<label class="model-choice ${m.available===false?'unavailable':''}"><input type="checkbox" name="model" value="${esc(m.id)}" ${m.available===false?'disabled':'checked'}><span><strong>${esc(m.id)} · ${esc(m.family)} · ${esc(m.kind)}</strong><small>${m.available===false?esc(m.unavailable_reason):`${esc(m.dataset||'Dataset belum dicantumkan')} · seed ${esc(m.seed??'—')}`}</small></span></label>`).join('');
 }).join(''):'<div class="empty-model"><span>⌘</span><div><strong>Model belum tersedia</strong><p>Tambahkan model terlatih dan konfigurasi fiturnya pada registry backend.</p></div></div>';
 batchUI?.refresh();
}

$('model-list').addEventListener('change',()=>batchUI?.refresh());
$('settings-open').onclick=()=>{$('api-url').value=state.api;$('settings').showModal();};$('settings-close').onclick=()=>$('settings').close();$('settings-form').onsubmit=e=>{e.preventDefault();const value=$('api-url').value.trim().replace(/\/+$/,'');if(value){const u=new URL(value);if(!['http:','https:'].includes(u.protocol)){toast('Gunakan URL HTTP atau HTTPS.');return;}}state.api=value;localStorage.setItem('deepguard-api',value);$('settings').close();connect();};$('refresh-models').onclick=()=>connect();
$('analyze').onclick=async()=>{if(state.singleBusy||state.batchBusy){toast('Tunggu analisis yang sedang berjalan.');return;}if(!state.buffer)return;let label;try{label=singleLabel();}catch(e){toast(e.message);return;}state.groundTruth=label;state.singleBusy=true;updateBusyControls();document.body.classList.add('busy');$('predictions').hidden=true;$('analyze').disabled=true;$('analyze').textContent='Menganalisis sinyal…';try{await new Promise(r=>setTimeout(r,30));state.audio=analyze(state.buffer,16000);state.inference=null;$('signal-empty').hidden=true;$('signal-result').hidden=false;$('signal-label').textContent='ANALISIS SELESAI';drawSignal();$('features-empty').hidden=true;$('features-content').hidden=false;const ids=[...document.querySelectorAll('input[name=model]:checked')].map(x=>x.value);if(ids.length){$('analyze').textContent='Menjalankan inferensi model…';const form=new FormData();form.append('audio',state.file);form.append('model_ids',JSON.stringify(ids));if(label!==null)form.append('ground_truth',String(label));try{state.inference=await api('/api/infer',{method:'POST',body:form});renderPredictions();}catch(e){toast('Fitur browser selesai. Inferensi gagal: '+e.message);}}else toast('Analisis audio selesai. Buka Eksplorasi fitur untuk detail.');}catch(e){toast('Analisis gagal: '+e.message);}finally{state.singleBusy=false;updateBusyControls();document.body.classList.remove('busy');$('analyze').innerHTML='Analisis ulang <span>↗</span>';}};
function renderPredictions(){const results=state.inference?.predictions||[];$('predictions').hidden=false;$('predictions').innerHTML=`<div class="card-heading"><h2>Hasil inferensi model</h2><span class="chip">THRESHOLD TRAIN / DEV</span></div>${state.inference?.ground_truth!==null&&state.inference?.ground_truth!==undefined?`<p class="footnote">Ground truth pengguna: <strong>${labelName(state.inference.ground_truth)}</strong>. Label ini tidak dipakai untuk menghitung skor.</p>`:''}<div class="prediction-grid">`+results.map(p=>`<article class="prediction"><small>${esc(p.model_id)}</small><strong>${esc(p.prediction||'ABSTAIN')}</strong><p>${p.status==='ok'?`Skor ${fmt(p.score,4)} · threshold ${fmt(p.threshold,4)}`:esc(p.reason)}</p><small>${p.status==='ok'?`${p.feature_count} fitur · ${p.missing_features} missing (imputer model)`:''}</small>${p.correct===true?'<p class="file-ready">Sesuai label pengguna</p>':p.correct===false?'<p class="warning">Tidak sesuai label pengguna</p>':''}${(p.warnings||[]).filter(w=>!w.startsWith('Serialisasi XGBoost versi lama:')).map(w=>`<p class="footnote warning">${esc(w)}</p>`).join('')}</article>`).join('')+'</div><p class="footnote">Skor model bukan persentase keyakinan kecuali model memiliki kalibrator. Hasil ini tidak membuktikan sumber atau identitas pembuat audio.</p>';}
function pythonFeatureCard(f,i){
 const residual=f._pipeline==='residual_modulation';
 const cols=residual?Object.keys(f).filter(k=>k.startsWith('res_')||k.startsWith('mod_')).map(k=>[k,k]):[['F0 median (Hz)','f0_median_hz_median'],['F0 std (Hz)','f0_std_hz_median'],['Voiced ratio','voiced_ratio_median'],['Jitter local (rasio)','jitter_local_median'],['Shimmer local (rasio)','shimmer_local_median'],['HNR (dB)','hnr_median'],['H1–H2 raw (dB)','h1h2_raw_median'],['Richness raw (dB)','richness_raw_db_median']];
 return `<div class="card-heading"><h2>${residual?'Residual LPC & modulasi':'Glotal v4/v5'} · konfigurasi ${i+1}</h2><span class="chip">${residual?'AGREGASI MEAN ANTARSEGMEN':'POOLED MEDIAN'}</span></div><div class="quality-grid">${cols.map(([label,key])=>`<div class="stat"><small>${esc(label)}</small><strong>${fmt(f[key],4)}</strong></div>`).join('')}</div><p class="footnote">${residual?`${f.n_segments} segmen · residual failure rate ${pct(f.residual_failure_rate)}`:`${f.n_windows} jendela aktif · active fraction ${pct(f.active_fraction)}`} · ${esc(f.analysis_status)}. Missing ditampilkan —; imputasi sesuai model training.</p>`;
}
function drawFeatures(){const a=state.audio;if(!a)return;const pythonFeatures=state.inference?.features||[];$('backend-feature-details').hidden=!pythonFeatures.length;$('backend-feature-details').innerHTML=pythonFeatures.map(pythonFeatureCard).join('');const coeff=[...a.mfcc,...a.lfcc].map(x=>x.mean),lo=Math.min(...coeff),hi=Math.max(...coeff);chart('coefficients',[{points:a.mfcc.map((x,i)=>({x:i+1,y:x.mean}))},{points:a.lfcc.map((x,i)=>({x:i+1,y:x.mean}))}],{xmin:1,xmax:20,ymin:lo-2,ymax:hi+2,xlabel:'koefisien'});chart('pitch',[{points:a.pitch.map(x=>({x:x.time,y:x.hz}))}],{xmax:a.duration,ymin:50,ymax:420,xlabel:'detik',ylabel:'Hz'});$('quality-details').innerHTML=[['RMS',fmt(a.rms_dbfs,1)+' dBFS'],['Clipping',pct(a.clipping)],['Median F0 (proksi)',a.f0_median?fmt(a.f0_median,1)+' Hz':'—'],['Voiced ratio (proksi)',pct(a.voiced_ratio)]].map(([k,v])=>`<div class="stat"><small>${k}</small><strong>${v}</strong></div>`).join('');const notes=[];if(a.duration<2)notes.push('Durasi kurang dari 2 detik; model dengan jendela 2 detik dapat abstain.');if(a.clipping>.005)notes.push('Terdeteksi clipping >0,5%; distorsi dapat memengaruhi fitur dan skor.');if(a.rms_dbfs< -40)notes.push('Level sinyal rendah; periksa noise dan kualitas rekaman.');if(a.voiced_ratio<.2)notes.push('Dukungan pitch rendah; proksi fonasi mungkin tidak stabil.');$('quality-notes').innerHTML=notes.map(x=>`<p class="warning">ⓘ ${esc(x)}</p>`).join('')+`<p>${a.sampled_frames} / ${a.total_frames} frame dianalisis (stride ${a.frame_stride}). Nilai eksplorasi browser tidak dimasukkan ke model v4/v5.</p>`;$('feature-table').innerHTML=a.mfcc.map((x,i)=>`<tr><td>c${i+1}</td><td>${fmt(x.mean)}</td><td>${fmt(x.std)}</td><td>${fmt(a.lfcc[i].mean)}</td><td>${fmt(a.lfcc[i].std)}</td></tr>`).join('');}
const template='sample_id,label,score,model,dataset,threshold,seed\nreal_001,0,0.12,MFCC_LR,my_test,0.5,2026\nfake_001,1,0.88,MFCC_LR,my_test,0.5,2026\n';$('download-template').onclick=()=>download('template-scores.csv',template,'text/csv');
function syntheticCSV(){const lines=['sample_id,label,score,model,dataset,threshold,seed'];['MFCC · LR','LFCC · LR','G3 glotal · LR','LFCC + G3 · LR'].forEach((model,m)=>{for(let i=0;i<80;i++){const y=i%2,u=(Math.sin((i+1)*(m+3)*17.23)*43758.5453)%1,noise=Math.abs(u);const score=Math.max(.01,Math.min(.99,.18+.57*y+(noise-.5)*(.95-m*.14)));lines.push(`synthetic_${i},${y},${score},${model},CONTOH SINTETIS,0.5,2026`);}});return lines.join('\n');}
function setRows(rows,source,synthetic){const groups=groupMetrics(rows);state.rows=rows;state.evalProvenance=null;state.sourceCSV=source;state.synthetic=synthetic;state.selected=0;const datasets=[...new Set(groups.map(x=>x.dataset))];$('dataset-filter').innerHTML=datasets.map(x=>`<option>${esc(x)}</option>`).join('');$('evaluation-source').textContent=`${source} · ${rows.length} baris · ${datasets.length} dataset${synthetic?' · DATA SINTETIS, bukan hasil penelitian':''}`;$('threshold-mode').value='frozen';$('custom-threshold-label').hidden=true;$('eval-content').hidden=false;updateEval();}
$('load-server-evaluation').onclick=async()=>{const button=$('load-server-evaluation');button.disabled=true;button.textContent='Memuat skor asli…';try{const data=await api('/api/evaluations/'+encodeURIComponent($('server-evaluation-select').value));setRows(data.rows,data.title,false);state.evalProvenance={run_id:data.run_id,scopes:data.scopes,excluded:data.excluded,source_sha256:data.source_sha256,note:data.note,threshold_policy:data.threshold_policy};updateEval();$('evaluation-source').textContent+=` · scope: ${data.scopes.join(', ')} · retained only`;toast('Hasil penelitian asli dimuat. Scope dan pengecualian tercatat dalam laporan.');}catch(e){toast('Gagal memuat hasil: '+e.message);}finally{button.disabled=false;button.textContent='Muat hasil asli ↗';}};
$('demo-metrics').onclick=()=>{try{setRows(parseCSV(syntheticCSV()),'Contoh sintetis untuk demonstrasi',true);toast('Data sintetis dimuat. Angka ini bukan performa model terlatih.');}catch(e){toast(e.message);}};
$('csv-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('CSV maksimum 10 MB.');const rows=parseCSV(await file.text());if(rows.length>100000)throw Error('CSV maksimum 100.000 baris.');setRows(rows,file.name,false);toast('Skor evaluasi berhasil dimuat.');}catch(e){toast(e.message);}e.target.value='';};
function updateEval(){try{const override=$('threshold-mode').value==='custom'?Number($('custom-threshold').value):null;if(override!==null&&($('custom-threshold').value===''||!Number.isFinite(override)))throw Error('Threshold harus berupa angka finite.');state.groups=groupMetrics(state.rows.filter(x=>x.dataset===$('dataset-filter').value),override);state.selected=Math.min(state.selected,state.groups.length-1);$('eval-badge').textContent=(state.synthetic?'DATA SINTETIS · ':'')+(override!==null?'EKSPLORASI · BUKAN HASIL FINAL':state.evalProvenance?.threshold_policy==='source_reported_unverified_selection'?'THRESHOLD LAPORAN · SELEKSI BELUM DIVERIFIKASI':state.evalProvenance?.threshold_policy==='standard_probability_0.5'?'THRESHOLD STANDAR 0.5':'THRESHOLD SUMBER');renderEval();}catch(e){toast(e.message);}}
$('dataset-filter').onchange=()=>{state.selected=0;updateEval();};$('threshold-mode').onchange=()=>{$('custom-threshold-label').hidden=$('threshold-mode').value!=='custom';updateEval();};$('custom-threshold').oninput=updateEval;
function renderEval(){const g=state.groups,chosen=g[state.selected];if(!chosen)return;$('metrics-table').innerHTML=g.map((m,i)=>`<tr tabindex="0" data-index="${i}" class="${i===state.selected?'selected':''}"><td><span style="color:${colors[i%colors.length]}">●</span> ${esc(m.model)} <small> / ${esc(m.seed||'—')}</small></td><td>${m.n}</td><td>${fmt(m.auc)}</td><td>${pct(m.eer)}</td><td>${pct(m.accuracy)}</td><td>${pct(m.balanced_accuracy)}</td><td>${pct(m.precision)}</td><td>${pct(m.recall)}</td><td>${fmt(m.f1)}</td><td>${fmt(m.mcc)}</td><td>${fmt(m.threshold)}</td></tr>`).join('');$('metrics-table').querySelectorAll('tr').forEach(x=>{const choose=()=>{state.selected=Number(x.dataset.index);renderEval();};x.onclick=choose;x.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}};});$('metric-cards').innerHTML=[['ROC–AUC',fmt(chosen.auc),'Keterpisahan skor · ↑ lebih baik'],['EQUAL ERROR RATE',pct(chosen.eer),'Interpolasi FPR = FNR · ↓ lebih baik'],['BALANCED ACCURACY',pct(chosen.balanced_accuracy),'Rerata recall REAL dan FAKE'],['F1 · FAKE',fmt(chosen.f1),'Keseimbangan precision dan recall']].map(([k,v,s])=>`<div class="card metric-card"><span>${k}</span><strong>${v}</strong><small>${esc(chosen.model)} · ${s}</small></div>`).join('');$('selected-model').textContent=chosen.model;$('confusion').innerHTML=[['TN · REAL → REAL',chosen.tn,false],['FP · REAL → FAKE',chosen.fp,true],['FN · FAKE → REAL',chosen.fn,true],['TP · FAKE → FAKE',chosen.tp,false]].map(([k,v,e])=>`<div class="${e?'wrong':''}"><small>${k}</small><strong>${v}</strong></div>`).join('');let body=`<p><strong>${esc(chosen.model)}</strong>: ${chosen.fp} rekaman REAL ditandai FAKE dan ${chosen.fn} rekaman FAKE lolos sebagai REAL.</p><p>FPR <strong>${pct(chosen.fpr)}</strong> · FNR <strong>${pct(chosen.fnr)}</strong> · AP FAKE <strong>${fmt(chosen.ap)}</strong> · TPR @ FPR ≤5% <strong>${pct(chosen.tpr_at_5)}</strong>.</p>`;if(!chosen.p||!chosen.n_real)body+='<p class="warning">Dataset hanya memuat satu kelas. AUC, EER, dan balanced accuracy tidak dapat dihitung.</p>';const reference=g.find(x=>x!==chosen&&paired(chosen,x));if(reference){const p=paired(chosen,reference);body+=`<p>Dibanding ${esc(reference.model)}, pada ${p.n} sampel identik: <strong>${p.aOnly}</strong> hanya model terpilih benar, <strong>${p.bOnly}</strong> hanya pembanding benar; ${p.bothWrong} sama-sama salah.</p>`;}else body+='<p>Perbandingan berpasangan membutuhkan sample_id, dataset, seed, dan label yang identik.</p>';body+='<p class="footnote">AUC dan EER tidak berubah ketika threshold eksplorasi diubah. Belum ada interval kepercayaan atau klaim signifikansi statistik.</p>';$('error-analysis').innerHTML=body;drawEval();}
function drawEval(){const g=state.groups;chart('roc',g.map((m,i)=>({color:colors[i%colors.length],points:m.auc===null?[]:m.roc.map(x=>({x:x.fpr,y:x.tpr}))})),{diagonal:true,xlabel:'False positive rate',ylabel:'True positive rate'});chart('pr',g.map((m,i)=>({color:colors[i%colors.length],points:m.ap===null?[]:m.pr.map(x=>({x:x.recall,y:x.precision}))})),{xlabel:'Recall',ylabel:'Precision'});$('roc-legend').innerHTML=g.map((m,i)=>`<span style="color:${colors[i%colors.length]}">● ${esc(m.model)} (${fmt(m.auc)})</span>`).join('');}
function report(){return {schema_version:1,generated_at:new Date().toISOString(),reference_repository:'https://github.com/alvinrw/Deepfake-audio-detection',batch:batchUI?.report()||null,audio:state.audio?{name:state.file.name,ground_truth:state.groundTruth,sha256:state.hash,exploration:state.audio}:null,inference:state.inference,evaluation:state.rows.length?{source:state.sourceCSV,synthetic:state.synthetic,scores:state.rows,provenance:state.evalProvenance,threshold_mode:$('threshold-mode').value,dataset:$('dataset-filter').value,metrics:state.groups.map(({rows,...m})=>m),note:'Label 0 REAL, 1 FAKE; score >= threshold predicts FAKE. Higher scores must indicate FAKE. EER uses linear ROC crossing interpolation. Undefined metrics are null.'}:null,limitations:['No trained weights supplied in the reference repository.','Browser features are exploratory and differ from Python model features.','No accuracy metrics for a single unlabeled audio file.','No generator attribution or proof of authenticity.','Synthetic examples do not represent model performance.','No bootstrap confidence intervals or significance test; datasets and seeds are kept separate.']};}
function renderReport(){const a=state.audio,m=state.inference?.predictions||[];$('report-body').innerHTML=`<span class="report-label">DEEPGUARD / ANALYSIS REPORT</span><h2>Ringkasan sesi</h2><p>${a?`Audio <strong>${esc(state.file.name)}</strong> dianalisis selama ${fmt(a.duration,2)} detik pada 16 kHz mono. SHA-256: <code style="overflow-wrap:anywhere">${state.hash}</code>.`:'Belum ada audio dianalisis. Unggah rekaman dan jalankan analisis untuk menghasilkan laporan.'}</p><h2>Inferensi & bukti akustik</h2>${m.length?m.map(p=>`<p><strong>${esc(p.model_id)}</strong>: ${esc(p.prediction||'ABSTAIN')} ${p.status==='ok'?`(skor ${fmt(p.score,4)}, threshold ${fmt(p.threshold,4)})`:esc(p.reason)}.</p>`).join(''):'<p>Belum ada prediksi model. Hasil keaslian tidak disimpulkan dari nama file atau fitur eksplorasi.</p>'}${a?`<p>Level RMS ${fmt(a.rms_dbfs,1)} dBFS; clipping ${pct(a.clipping)}; median pitch proksi ${a.f0_median?fmt(a.f0_median,1)+' Hz':'tidak tersedia'}; voiced ratio proksi ${pct(a.voiced_ratio)}.</p>`:''}<h2>Perbandingan model & fitur</h2>${state.rows.length?`<p>${state.evalProvenance?`${esc(state.evalProvenance.note||'')} Kebijakan threshold: <strong>${esc(state.evalProvenance.threshold_policy||'train_dev_frozen')}</strong>. Run <strong>${esc(state.evalProvenance.run_id)}</strong> · scope <strong>${esc(state.evalProvenance.scopes.join(', '))}</strong>. Hanya retained samples; dikecualikan per model: ${esc(JSON.stringify(state.evalProvenance.excluded))}. `:''}Sumber: <strong>${esc(state.sourceCSV)}</strong>. ${state.synthetic?'<span class="warning">DATA SINTETIS — hanya demonstrasi.</span>':''} Dataset aktif: ${esc($('dataset-filter').value)}. Threshold ${$('threshold-mode').value==='custom'?'eksplorasi, bukan hasil final':'sesuai kebijakan sumber'}.</p>`+state.groups.map(g=>`<p><strong>${esc(g.model)}</strong> / seed ${esc(g.seed||'—')} / n=${g.n}: AUC ${fmt(g.auc)}, EER ${pct(g.eer)}, balanced accuracy ${pct(g.balanced_accuracy)}, F1 ${fmt(g.f1)}.</p>`).join(''):'<p>Impor skor berlabel untuk menghitung metrik, ROC, precision–recall, dan kesalahan berpasangan.</p>'}<h2>Batas interpretasi</h2><ul><li>Fitur browser bersifat eksploratif. Inferensi memakai ekstraktor Python dan konfigurasi model yang terdaftar.</li><li>Jitter, shimmer, HNR, dan harmonik adalah proksi fonasi; bukan pengukuran langsung aliran glotal.</li><li>Skor model tidak otomatis merupakan probabilitas terkalibrasi. Satu rekaman tanpa label tidak menghasilkan akurasi.</li><li>Tidak ada atribusi generator atau bukti definitif keaslian. Periksa generalisasi lintas dataset dan kondisi kanal.</li><li>Belum ada interval kepercayaan bootstrap atau uji signifikansi. Jangan menyimpulkan perbedaan bermakna hanya dari peringkat metrik.</li></ul><h2>Provenans</h2><p>Konsep dan identitas DeepGuard dikembangkan dari <a href="https://github.com/alvinrw/Deepfake-audio-detection" target="_blank" rel="noreferrer" style="color:var(--cyan)">repo alvinrw ↗</a>. Backend terintegrasi dengan repo glotal dan residual modulation terpisah. Bobot lokal tidak ditanamkan pada frontend.</p>`;$('report-body').insertAdjacentHTML('beforeend',batchUI?.reportHTML()||'');}
function exportReport(){download('deepguard-report.json',report());toast('Laporan JSON berhasil diekspor.');}for(const id of ['export-top','export-report'])$(id).onclick=exportReport;$('export-features').onclick=()=>{if(!state.audio){toast('Analisis audio terlebih dahulu.');return;}download('deepguard-features.json',{file:state.file.name,sha256:state.hash,...state.audio});};$('export-metrics').onclick=()=>{const keys=['dataset','model','seed','n','threshold','auc','eer','accuracy','balanced_accuracy','precision','recall','f1','mcc','tp','tn','fp','fn','ap','fpr','fnr'];const quote=x=>'"'+String(x??'').replaceAll('"','""')+'"';download('deepguard-metrics.csv',keys.join(',')+'\n'+state.groups.map(g=>keys.map(k=>quote(g[k])).join(',')).join('\n'),'text/csv');};

function singleLabel(){
 if(!$('single-label-enabled').checked)return null;
 const label=normalizeLabel($('single-label').value);if(label===null)throw Error('Pilih REAL atau FAKE, atau matikan label ground truth.');return label;
}
function updateBusyControls(){
 const locked=state.singleBusy||state.batchBusy;
 for(const id of ['audio-file','sample-audio','refresh-models','single-label-enabled'])$(id).disabled=locked;
 $('single-label').disabled=locked||!$('single-label-enabled').checked;
 $('analyze').disabled=locked||!state.buffer;
 document.querySelectorAll('input[name=model]').forEach(input=>input.disabled=locked||state.models.find(m=>m.id===input.value)?.available===false);
}
function labelChanged(){
 state.groundTruth=$('single-label-enabled').checked?normalizeLabel($('single-label').value):null;
 state.inference=null;$('predictions').hidden=true;updateBusyControls();
 $('single-label-note').textContent=$('single-label-enabled').checked?`Ground truth: ${state.groundTruth===null?'pilih REAL / FAKE':labelName(state.groundTruth)}. Jalankan analisis untuk mengevaluasi label; label tidak menjadi input model.`:'Opsional. Label dipakai untuk evaluasi, bukan input model.';
}
$('single-label-enabled').onchange=labelChanged;$('single-label').onchange=labelChanged;
batchUI=initBatch({api,toast,models:()=>state.models,busy:()=>state.singleBusy,onBusy:value=>{state.batchBusy=value;updateBusyControls();},download,setEvaluation:(rows,batch)=>{
 setRows(rows,'Skor batch unggahan lokal',false);
 state.evalProvenance={run_id:batch.run_id,scopes:['user_labeled_batch_scored_subset'],threshold_policy:'train_dev_frozen',excluded:Object.fromEntries(batch.summaries.map(s=>[s.model,{abstained:s.abstained,error:s.error}])),coverage:batch.summaries.map(({rows,metrics,...s})=>s),note:'Hanya skor berlabel yang lolos. Coverage per kelas, abstain dan error seluruh batch ada pada halaman Analisis batch dan laporan JSON.'};updateEval();go('evaluation');
}});

let resizeTimer;window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(()=>{if(state.page==='inference')drawSignal();if(state.page==='features')drawFeatures();if(state.page==='evaluation'&&state.groups.length)drawEval();},150);});window.addEventListener('hashchange',()=>go(location.hash.slice(1)));go(location.hash.slice(1));connect(true);
